Etc = {
    init: async function (app, container) {
        app = app || session.app;
        container = container || $(".component[name=Etc]");
        $("[name=cultureFlagLayout]", container).kendoDropDownList({
            dataSource: [
                {key: "text", text: "[resource_displayname[text]]"},
                {key: "picture", text: "[resource_displayname[picture]]"}
            ],
            dataTextField: "text",
            dataValueField: "key",
        });
    }
}
